import csv
import re

# Load task A data to have exact numbers
with open('results/data/task_a_log.csv', mode='r', encoding='utf-8') as f:
    rows = list(csv.DictReader(f))

data = {}
for r in rows:
    num = int(r['Algorithm_Number'])
    if num not in data:
        data[num] = {}
    data[num][r['Problem']] = r

